function finishPage(){window.scrollTo(0,0);const heading=document.body.classList.contains('mobile-page-open')?$('.mobile-page-header h1',modal):$('h1',app);if(heading){document.title=`${(heading.innerText||heading.textContent).replace(/\s+/g,' ').trim()} · ZARURIYAT`;heading.tabIndex=-1;heading.focus({preventScroll:true});}document.querySelectorAll('.mobile-bottom-bar .mb-item').forEach(a=>{const route=location.hash.slice(1).split('?')[0];const target=a.hash?.slice(1)||({request:'request',track:'track',login:'login',menu:'cabinet/menu',cabinet:'cabinet/overview'}[a.dataset.action]);const active=target===route||(target==='services'&&route==='service')||(target==='cabinet/cases'&&route==='cabinet/case')||(target==='cabinet/menu'&&route==='cabinet/settings');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
