function stat(label,value,note,ico,emphasis=false){return `<article class="stat ${emphasis?'emphasis':''}"><div class="stat-label">${esc(tr(label))}${icon(ico)}</div><div class="stat-value">${esc(value)}</div><p class="stat-foot">${esc(tr(note))}</p></article>`;}
function staffOverview(){
 const isDir=state.user.role==='director',isCyr=state.script==='cyr';
 const s=state.stats,max=Math.max(1,...(s.categories||[]).map(c=>c.count));
 const headingAction=`<div style="display:flex;gap:10px">${isDir?`<button class="btn outline" data-action="user-new">${icon('users')} ${isCyr?'Янги ходим':'Yangi xodim'}</button>`:''}${newRequestButton()}</div>`;
 return `${pageHeading(isDir?(isCyr?'Раҳбар кабинети':'Rahbar kabineti'):(isCyr?'Координатор иш майдони':'Koordinator ish maydoni'),`${date(new Date().toISOString())} · ${isCyr?'Тизимнинг умумий ҳолати ва кўрсаткичлари':'Tizimning umumiy holati va ko‘rsatkichlari'}`,headingAction)}<div class="stat-grid">${stat(isCyr?'Жами мурожаатлар':'Jami murojaatlar',s.total,isCyr?'Барча вақт бўйича':'Barcha vaqt bo‘yicha','layers',true)}${stat(isCyr?'Бугун келиб тушди':'Bugun kelib tushdi',s.today,isCyr?'Янги мурожаатлар':'Yangi murojaatlar','file')}${stat(isCyr?'Очиқ кейслар':'Ochiq keyslar',s.open,isCyr?'Жараёндаги кейслар':'Jarayondagi keyslar','clock')}${stat(isCyr?'Якунланган':'Yakunlangan',s.completed,isCyr?'Муваффақиятли якунланган':'Muvaffaqiyatli yakunlangan','check')}</div><div class="panel"><header class="panel-head"><div><h2>${isCyr?'Сўнгги мурожаатлар ва кейслар':'So‘nggi murojaatlar va keyslar'}</h2><p>${isCyr?'Янги эҳтиёжлар ва ташкил қилинаётган хизматлар':'Yangi ehtiyojlar va tashkil qilinayotgan xizmatlar'}</p></div><a class="text-btn small-text" href="#cabinet/cases">${isCyr?'Барчаси':'Barchasi'} ${icon('arrow')}</a></header>${caseTable(s.recent||state.cases.slice(0,6))}</div><div class="overview-grid"><section class="panel"><header class="panel-head"><h2>${isCyr?'Хизмат йўналишлари бўйича':'Xizmat yo‘nalishlari bo‘yicha'}</h2><span class="pill">${isCyr?'Жами':'Jami'} ${esc(s.total)}</span></header><div class="panel-body">${(s.categories||[]).filter(c=>c.count>0).map(c=>`<div class="bar-row"><div class="bar-top"><span>${esc(category(c.name))}</span><b>${esc(c.count)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,c.count/max*100)}%"></div></div></div>`).join('')||empty(isCyr?'Ҳали маълумот йўқ':'Hali ma’lumot yo‘q',isCyr?'Мурожаатлар келиши билан кўринади.':'Murojaatlar kelishi bilan ko‘rinadi.')}</div></section><section class="panel"><header class="panel-head"><h2>${isCyr?'Платформа бошқаруви':'Platforma boshqaruvi'}</h2></header><div class="task-card">${icon('briefcase')}<div><h3>${isCyr?'Ҳамкорлар базаси':'Hamkorlar bazasi'}</h3><p>${isCyr?'Маълумотномадаги мутахассис ва ташкилотлар':'Ma’lumotnomadagi mutaxassis va tashkilotlar'}</p></div><span class="pill">${esc(s.partners)}</span></div><div class="task-card">${icon('users')}<div><h3>${isCyr?'Мижозлар':'Mijozlar'}</h3><p>${isCyr?'Рўйхатдан ўтган мижозлар ҳисоби':'Ro‘yxatdan o‘tgan mijozlar hisobi'}</p></div><span class="pill">${esc(s.clients)}</span></div><div class="task-card">${icon('home')}<div><h3>${isCyr?'Оила пакетлари':'Oila paketlari'}</h3><p>${isCyr?'Амалдаги оилавий пакетлар':'Amaldagi oilaviy paketlar'}</p></div><span class="pill">${esc(s.packagesCount||0)} (${esc(s.activePackagesCount||0)} ${isCyr?'фаол':'faol'})</span></div><div class="task-card">${icon('star')}<div><h3>${isCyr?'Мижозлар баҳоси':'Mijozlar bahosi'}</h3><p>${isCyr?'Якунланган хизматлар бўйича (1–5 балл)':'Yakunlangan xizmatlar bo‘yicha (1–5 ball)'}</p></div><span class="pill">${s.averageRating==null?(isCyr?'Ҳали йўқ':'Hali yo‘q'):`${Number(s.averageRating).toFixed(1)} / 5`}</span></div><div class="panel-body"><div class="notice" style="margin:0">${isCyr?'ZARURIYAT — инсон мутахассисни ўзи қидирмайди, тизим керакли ечимни ташкил қилади.':'ZARURIYAT — inson mutaxassisni o‘zi qidirmaydi, tizim kerakli yechimni tashkil qiladi.'}</div></div></section></div>`;
}
function personalOverview(){const partner=state.user.role==='partner',open=state.cases.filter(c=>!terminal(c)).length;return `${pageHeading(`${tr('Assalomu alaykum')}, ${state.user.name.split(' ')[0]}.`,partner?tr("Sizga biriktirilgan xizmatlarni shu yerdan boshqaring."):tr("Murojaatlaringiz va yaqinlaringiz uchun yordam bir joyda."),partner?'':newRequestButton())}<div class="stat-grid">${stat(partner?'Biriktirilgan ishlar':'Murojaatlarim',state.cases.length,'Yuklangan murojaatlar bo‘yicha','file',true)}${stat('Jarayonda',open,'Yuklangan murojaatlar bo‘yicha','clock')}${stat('Yakunlangan',state.cases.filter(c=>c.status==='completed').length,'Yuklangan murojaatlar bo‘yicha','check')}${stat(partner?'Xizmatlar':'Oila paketlari',partner?state.cases.reduce((n,c)=>n+c.services.length,0):state.packages.length,partner?'Sizga biriktirilgan xizmatlar':'Hisobingizga biriktirilgan',partner?'briefcase':'home')}</div><div class="section-heading"><div><h2 style="font-size:21px">${partner?'Mening xizmatlarim':'So‘nggi murojaatlarim'}</h2></div><a href="#cabinet/cases" class="text-btn small-text">${tr("Barchasi")} ${icon('arrow')}</a></div>${caseCards(state.cases.slice(0,6))}${!partner&&state.packages.length?`<div style="margin-top:28px"><h2 style="font-size:21px;margin-bottom:18px">${tr("Oila paketingiz")}</h2>${packageCards()}</div>`:''}`;}
function caseCards(cases){if(!cases.length)return `<div class="panel">${empty('Hozircha murojaatlar yo‘q',state.user.role==='partner'?'Sizga xizmat biriktirilganda bu yerda ko‘rinadi.':'Birinchi murojaatingizni qoldiring. Jarayonni shu yerdan kuzatib borasiz.',state.user.role==='client'?newRequestButton():'')}</div>`;return `<div class="case-cards">${cases.map(c=>`<article class="client-case"><div class="client-case-top"><span class="small-text muted">${esc(c.number)}</span>${badge(c.status)}</div><h3>${esc(state.user.role==='partner'?(c.services[0]?.title||category(c.category)):category(c.category))}</h3><p>${esc(c.description||tr("Xizmat tafsilotlarini ko‘ring."))}</p>${staff()?`<dl class="case-card-metadata"><div class="record-full"><dt>${tr('Mijoz')}</dt><dd>${esc(c.name||'?')}</dd></div><div><dt>${tr('Koordinator')}</dt><dd>${esc(c.coordinatorName||tr('Biriktirilmagan'))}</dd></div><div><dt>${tr('Rejalashtirilgan muddat')}</dt><dd>${date(c.dueAt)}${overdue(c)?`<span class="pill red">${tr('Muddati o?tgan')}</span>`:''}</dd></div></dl>${c.priority==='urgent'?`<span class="pill red">${tr('Shoshilinch')}</span>`:''}`:''}${state.user.role==='partner'?`<div class="member-tags">${c.services.map(s=>`<span>${esc(tr(serviceNames[s.status]))}</span>`).join('')}</div>`:''}<div class="client-case-bottom"><span>${date(c.createdAt)}</span><button class="text-btn small-text" data-action="case" data-id="${c.id}">${tr("Tafsilotlar")} ${icon('arrow')}</button></div></article>`).join('')}</div>`;}
function caseTable(cases){if(mobileViewport())return caseCards(cases);if(!cases.length)return empty('Murojaat topilmadi','Filtrlarni o‘zgartiring yoki yangi murojaat yarating.');return `<div class="table-scroll"><table><thead><tr><th>${tr("Murojaat / mijoz")}</th><th>${tr("Yo‘nalish")}</th><th>${tr("Holat")}</th><th>${tr("Mas’ul")}</th><th>${tr("Muddat")}</th><th></th></tr></thead><tbody>${cases.map(c=>`<tr class="clickable" data-action="case" data-id="${c.id}"><td><button class="row-link" data-action="case" data-id="${c.id}">${esc(c.number)}</button><br><small>${esc(c.name)}</small></td><td>${esc(category(c.category))}${c.priority==='urgent'?`<br><span class="pill red" style="margin-top:6px">${tr("Shoshilinch")}</span>`:''}</td><td>${badge(c.status)}</td><td>${esc(c.coordinatorName||tr("Biriktirilmagan"))}</td><td>${overdue(c)?`<span class="pill red">${tr("Muddati o‘tgan")}</span><br>`:''}<small>${date(c.dueAt)}</small></td><td>${icon('arrow')}</td></tr>`).join('')}</tbody></table></div>`;}
function filteredCases(){return state.cases;}
